update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(112,null::text,$$Progressão de regime$$,$$A pena privativa de liberdade é executada de forma progressiva, com transferência para regime menos rigoroso, determinada pelo juiz, quando o preso tiver cumprido ao menos 1/6 (um sexto) da pena no regime anterior e seu mérito indicar a progressão, observadas as exceções do artigo. O texto fixa percentuais distintos nos incisos, como 25% (vinte e cinco por cento) no inciso I, 30% (trinta por cento) no inciso II, 20% (vinte por cento) no inciso III, 70% (setenta por cento) no inciso V e 80% (oitenta por cento) no inciso VII, e os incisos IX e X constam como vetados. Exige-se boa conduta carcerária e resultados do exame criminológico (§ 1º), a decisão é motivada e precedida de manifestação do Ministério Público e do defensor (§ 2º), a falta grave interrompe o prazo (§ 6º) e o bom comportamento é readquirido após 1 (um) ano do fato ou antes, com o cumprimento do requisito temporal (§ 7º).$$),
(113,null,$$Ingresso no regime aberto$$,$$O ingresso do condenado em regime aberto supõe a aceitação de seu programa e das condições impostas pelo juiz.$$),
(114,null,$$Requisitos do regime aberto$$,$$Só pode ingressar no regime aberto o condenado que estiver trabalhando ou comprovar a possibilidade de fazê-lo imediatamente (inciso I) e apresentar, pelos antecedentes e pelos resultados do exame criminológico, fundados indícios de que irá ajustar-se ao novo regime, com autodisciplina, baixa periculosidade e senso de responsabilidade (inciso II). As pessoas referidas no artigo 117 podem ser dispensadas do trabalho (parágrafo único).$$),
(115,null,$$Condições do regime aberto$$,$$O juiz pode estabelecer condições especiais para a concessão do regime aberto, entre elas a fiscalização por monitoramento eletrônico, sem prejuízo das condições gerais e obrigatórias: permanecer no local designado durante o repouso e nos dias de folga (inciso I), sair para o trabalho e retornar nos horários fixados (inciso II), não se ausentar da cidade onde reside sem autorização judicial (inciso III) e comparecer a juízo quando determinado (inciso IV).$$),
(116,null,$$Modificação das condições$$,$$O juiz pode modificar as condições estabelecidas, de ofício, a requerimento do Ministério Público, da autoridade administrativa ou do condenado, desde que as circunstâncias assim o recomendem.$$),
(117,null,$$Prisão domiciliar do regime aberto$$,$$Só se admite o recolhimento do beneficiário de regime aberto em residência particular quando se tratar de condenado maior de 70 (setenta) anos (inciso I), condenado acometido de doença grave (inciso II), condenada com filho menor ou deficiente físico ou mental (inciso III) ou condenada gestante (inciso IV).$$),
(118,null,$$Regressão de regime$$,$$A execução da pena privativa de liberdade fica sujeita à forma regressiva, com transferência para qualquer dos regimes mais rigorosos, quando o condenado praticar fato definido como crime doloso ou falta grave (inciso I) ou sofrer condenação, por crime anterior, cuja pena, somada ao restante da pena em execução, torne incabível o regime (inciso II, artigo 111). O condenado é transferido do regime aberto também se frustrar os fins da execução ou não pagar a multa cumulativamente imposta, podendo pagá-la (§ 1º), e nas hipóteses do inciso I e do § 1º deve ser ouvido previamente (§ 2º).$$),
(119,null,$$Normas complementares do regime aberto$$,$$A legislação local pode estabelecer normas complementares para o cumprimento da pena privativa de liberdade em regime aberto (artigo 36, § 1º, do Código Penal).$$),
(119,$$Art. 119-A$$,$$Exame criminológico nos crimes contra a dignidade sexual$$,$$O condenado por crimes contra a dignidade sexual só ingressa em regime mais benéfico ou percebe benefício penal que autorize a saída do estabelecimento se os resultados do exame criminológico afirmarem a existência de indícios de que não voltará a cometer crimes da mesma natureza.$$),
(120,null,$$Permissão de saída$$,$$Os condenados em regime fechado ou semi-aberto e os presos provisórios podem obter permissão para sair do estabelecimento, mediante escolta, em caso de falecimento ou doença grave do cônjuge, companheira, ascendente, descendente ou irmão (inciso I) ou de necessidade de tratamento médico (inciso II). A permissão é concedida pelo diretor do estabelecimento (parágrafo único).$$),
(121,null,$$Duração da permissão de saída$$,$$A permanência do preso fora do estabelecimento tem a duração necessária à finalidade da saída.$$),
(122,null,$$Saída temporária$$,$$Os condenados em regime semi-aberto podem obter autorização para saída temporária, sem vigilância direta, no caso de frequência a curso supletivo profissionalizante, de instrução do 2º grau ou superior, na Comarca do Juízo da Execução (inciso II); os incisos I e III constam como revogados. A ausência de vigilância direta não impede a monitoração eletrônica, quando determinada pelo juiz (§ 1º), e não tem direito à saída temporária ou a trabalho externo sem vigilância direta o condenado por crime hediondo ou com violência ou grave ameaça contra pessoa (§ 2º).$$),
(123,null,$$Requisitos da saída temporária$$,$$A autorização é concedida por ato motivado do juiz da execução, ouvidos o Ministério Público e a administração penitenciária, e depende de comportamento adequado (inciso I), cumprimento mínimo de 1/6 (um sexto) da pena, se primário, e 1/4 (um quarto), se reincidente (inciso II), e compatibilidade do benefício com os objetivos da pena (inciso III).$$),
(125,null,$$Revogação da saída temporária$$,$$O benefício é automaticamente revogado quando o condenado praticar fato definido como crime doloso, for punido por falta grave, desatender as condições impostas na autorização ou revelar baixo grau de aproveitamento do curso. A recuperação do direito depende da absolvição no processo penal, do cancelamento da punição disciplinar ou da demonstração do merecimento do condenado (parágrafo único).$$),
(126,null,$$Remição pelo trabalho ou pelo estudo$$,$$O condenado em regime fechado ou semiaberto pode remir, por trabalho ou por estudo, parte do tempo de execução da pena. A contagem é de 1 (um) dia de pena a cada 12 (doze) horas de frequência escolar (§ 1º, inciso I) e de 1 (um) dia de pena a cada 3 (três) dias de trabalho (§ 1º, inciso II). O estudo pode ser presencial ou a distância (§ 2º), o tempo a remir por estudo é acrescido de 1/3 (um terço) na conclusão do ensino fundamental, médio ou superior (§ 5º), a remição se aplica à prisão cautelar (§ 7º) e é declarada pelo juiz da execução, ouvidos o Ministério Público e a defesa (§ 8º).$$),
(127,null,$$Perda de dias remidos$$,$$Em caso de falta grave, o juiz pode revogar até 1/3 (um terço) do tempo remido, observado o art. 57, recomeçando a contagem a partir da data da infração disciplinar.$$),
(128,null,$$Tempo remido como pena cumprida$$,$$O tempo remido é computado como pena cumprida, para todos os efeitos.$$),
(129,null,$$Registro mensal de trabalho e estudo$$,$$A autoridade administrativa encaminha mensalmente ao juízo da execução cópia do registro de todos os condenados que estejam trabalhando ou estudando, com informação dos dias de trabalho ou das horas de frequência escolar ou de atividades de ensino. O condenado autorizado a estudar fora do estabelecimento comprova mensalmente, por declaração da unidade de ensino, a frequência e o aproveitamento escolar (§ 1º), e recebe a relação de seus dias remidos (§ 2º).$$),
(130,null,$$Falsa declaração para remição$$,$$Constitui o crime do artigo 299 do Código Penal declarar ou atestar falsamente prestação de serviço para fim de instruir pedido de remição.$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;